/// The golden of the facts of the fixed corpus (docs/specs/
/// dart-toolchain.md, section 6.1).
///
/// `test/fixtures/facts_corpus/*.dart.txt` are run through the extractor and
/// the codec; the result is compared with
/// `test/goldens/facts/corpus_v<factsFormatVersion>.json`. A change to what
/// the lexer or a recognizer produces changes the rendering, and the test
/// fails until `factsFormatVersion` is raised and the golden regenerated by
/// `tool/update_facts_golden.dart`.
library;

import 'dart:convert';
import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:stagelatch/src/domain/repo_path.dart';
import 'package:stagelatch/src/infrastructure/dart/facts_codec.dart';
import 'package:stagelatch/src/infrastructure/dart/syntactic_facts.dart';

/// Where the fixed corpus is, relative to the repository root.
const String corpusDirectory = 'test/fixtures/facts_corpus';

/// The golden of [version], relative to the repository root.
String goldenPath(int version) => 'test/goldens/facts/corpus_v$version.json';

/// The golden of the current [factsFormatVersion]: every corpus file, by
/// name, with the canonical encoding of its facts, indented for review.
///
/// Files are read in name order, and their text is read as UTF-8 with line
/// endings as stored. The extractor runs with its default test functions and
/// `myTest`, so the configurable part of the facts is covered.
String renderFactsGolden() {
  final files =
      Directory(corpusDirectory)
          .listSync()
          .whereType<File>()
          .where((file) => file.path.endsWith('.dart.txt'))
          .toList()
        ..sort((a, b) => a.path.compareTo(b.path));
  const extractor = SyntacticFacts(
    testFunctions: {'group', 'myTest', 'test', 'testWidgets'},
  );
  final rendered = <String, Object?>{
    for (final file in files)
      p.basename(file.path): jsonDecode(
        encodeFacts(
          extractor.extract(
            file.readAsStringSync(),
            RepoPath(p.basename(file.path).replaceFirst(RegExp(r'\.txt$'), '')),
          ),
        ),
      ),
  };
  return '${const JsonEncoder.withIndent('  ').convert({
    'factsFormatVersion': factsFormatVersion,
    'testFunctions': ['group', 'myTest', 'test', 'testWidgets'],
    'files': rendered,
  })}\n';
}
